def find_all_frames_simple(g):
    """Simpler approach: check every possible rectangle"""
    frames = []
    rows, cols = len(g), len(g[0])
    bg = 4

    for r1 in range(rows):
        for c1 in range(cols):
            if g[r1][c1] == bg:
                continue

            color = g[r1][c1]

            # Find the extent of this color's rectangular structure
            # Look for matching color on same row
            r1_end = c1
            while r1_end + 1 < cols and g[r1][r1_end + 1] == color:
                r1_end += 1

            if r1_end <= c1:
                continue  # Not enough width

            c1_end = r1_end - 1

            # Now find how far down this column pattern goes
            # Left side should stay at c1
            height = 1
            while height + 1 < rows:
                r2 = r1 + height
                if r2 >= rows or g[r2][c1] != color:
                    break

                # Check if right side at c1_end exists
                if c1_end >= cols or g[r2][c1_end] != color:
                    break

                height += 1

            if height < 2:
                r2 = r1
                c1_start = c1
            else:
                r2 = r1 + height - 1
                c1_start = c1
                c1_end_actual = c1_end

            # Verify it's a hollow rectangle
            valid = True
            for rr in range(r1, r2 + 1):
                for cc in range(c1_start, c1_end_actual + 1):
                    on_boundary = (rr == r1 or rr == r2 or cc == c1_start or cc == c1_end_actual)
                    expected = color if on_boundary else bg

                    actual = g[rr][cc]
                    if on_boundary and actual != color:
                        valid = False
                    elif not on_boundary and actual != bg:
                        valid = False
                if not valid:
                    break

            if valid:
                # Mark this area as covered so we don't count overlapping frames
                # Actually, for same-color frames, they might overlap spatially!
                # We need to check if this is already recorded
                is_new = True
                for (fr_color, fr_r1, fr_r2, fr_c1, fr_c2) in frames:
                    if fr_color != color:
                        continue
                    # Check if this rectangle overlaps significantly
                    if max(r1, fr_r1) <= min(r2, fr_r2) and max(c1_start, fr_c1) <= min(c1_end_actual, fr_c2):
                        is_new = False
                        break

                if is_new:
                    frames.append((color, r1, r2, c1_start, c1_end_actual))

    return frames

