from itertools import combinations

def get_unique_maximal_frames(g):
    """Get unique maximal hollow rectangles, one per color"""
    frames = []
    rows, cols = len(g), len(g[0])
    bg = 4

    # Get bounding boxes for each color
    colors_positions = {}
    for r in range(rows):
        for c in range(cols):
            color = g[r][c]
            if color == bg:
                continue
            if color not in colors_positions:
                colors_positions[color] = []
            colors_positions[color].append((r, c))

    for color, positions in colors_positions.items():
        positions_set = set(positions)

        # Try all pairs of top-left corners to find rectangles
        found_this_color = set()

        for p1_idx, p2_idx in combinations(range(len(positions)), 2):
            p1, p2 = positions[p1_idx], positions[p2_idx]

            # Find minimal bounding box containing both points
            r_min = min(p[0] for p in [p1, p2])
            r_max = max(p[0] for p in [p1, p2])
            c_min = min(p[1] for p in [p1, p2])
            c_max = max(p[1] for p in [p1, p2])

            # Expand to find the full rectangle
            final_r_min, final_r_max, final_c_min, final_c_max = r_min, r_max, c_min, c_max

            # Extend vertically if possible
            while final_r_min > 0:
                if all(g[final_r_min - 1][c] == color for c in range(final_c_min, final_c_max + 1)):
                    final_r_min -= 1
                else:
                    break

            while final_r_max < rows - 1:
                if all(g[final_r_max + 1][c] == color for c in range(final_c_min, final_c_max + 1)):
                    final_r_max += 1
                else:
                    break

            # Extend horizontally if possible
            while final_c_min > 0:
                if all(g[r][final_c_min - 1] == color for r in range(final_r_min, final_r_max + 1)):
                    final_c_min -= 1
                else:
                    break

            while final_c_max < cols - 1:
                if all(g[r][final_c_max + 1] == color for r in range(final_r_min, final_r_max + 1)):
                    final_c_max += 1
                else:
                    break

            # Now verify this is a hollow rectangle
            # Create set of all cells that ARE part of this frame
            boundary_cells = set()
            for rr in range(final_r_min, final_r_max + 1):
                for cc in range(final_c_min, final_c_max + 1):
                    on_boundary = (rr == final_r_min or rr == final_r_max or cc == final_c_min or cc == final_c_max)
                    if on_boundary:
                        boundary_cells.add((rr, cc))

            # Check if all boundary cells have color and interior is bg
            frame_valid = True
            for rr, cc in boundary_cells:
                if g[rr][cc] != color:
                    frame_valid = False
                    break

            if not frame_valid:
                continue

            # Check interior
            for rr in range(final_r_min + 1, final_r_max):
                for cc in range(final_c_min + 1, final_c_max):
                    if g[rr][cc] != bg:
                        frame_valid = False
                        break
                if not frame_valid:
                    break

            if frame_valid:
                # Check maximality - no larger rectangle of same color contains this
                too_small = False
                for dr in range(-3, 4):
                    for dc in range(-3, 4):
                        nr1, nr2, nc1, nc2 = final_r_min + dr, final_r_max + dr, final_c_min + dc, final_c_max + dc
                        if nr1 < 0 or nr2 >= rows or nc1 < 0 or nc2 >= cols:
                            continue

                        new_boundary = set()
                        for rr in range(nr1, nr2 + 1):
                            for cc in range(nc1, nc2 + 1):
                                on_b = (rr == nr1 or rr == nr2 or cc == nc1 or cc == nc2)
                                if on_b:
                                    new_boundary.add((rr, cc))

                        all_boundary_match = all(pos in positions_set for pos in new_boundary)
                        if not all_boundary_match:
                            continue

                        # Interior check
                        all_interior_bg = True
                        for rr in range(nr1 + 1, nr2):
                            for cc in range(nc1 + 1, nc2):
                                if (rr, cc) in positions_set or g[rr][cc] != bg:
                                    all_interior_bg = False
                                    break
                            if not all_interior_bg:
                                break

                        if all_interior_bg:
                            # This rectangle can be extended, mark current as non-maximal
                            if (nr1, nr2, nc1, nc2) in [(f[1], f[2], f[3], f[4]) for f in found_this_color]:
