def find_frames_in_grid(grid, target_color, bg_color=4):
    """Find all hollow rectangular frames of target_color"""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    frames = []
    visited = set()

    # Find all pixels of target color sorted top-left to bottom-right
    target_pos = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == target_color:
                target_pos.append((r, c))

    print(f"Found {len(target_pos)} pixels of color {target_color}")

    def expand_rect(start_r, start_c):
        """Expand from corner to find full rectangular border"""
        # Expand right along top edge
        c_end = start_c
        while c_end + 1 < cols and grid[start_r][c_end+1] == target_color:
            c_end += 1

        # Expand down along left edge  
        r_end = start_r
        while r_end + 1 < rows and any(grid[r_end+1][c] == target_color for c in range(start_c, c_end+1)):
            r_end += 1

        h, w = r_end - start_r + 1, c_end - start_c + 1
        if h < 3 or w < 3:
            return None

        # Verify it's a complete frame
        is_frame = True
        # Top
        if not all(grid[start_r][c] == target_color for c in range(start_c, c_end+1)):
            is_frame = False
        # Bottom
        if not all(grid[r_end][c] == target_color for c in range(start_c, c_end+1)):
            is_frame = False
        # Left
        if not all(grid[r][start_c] == target_color for r in range(start_r, r_end+1)):
            is_frame = False
        # Right
        if not all(grid[r][c_end] == target_color for r in range(start_r, r_end+1)):
            is_frame = False

        if is_frame:
            interior = [(r,c) for r in range(start_r+1, r_end) 
                       for c in range(start_c+1, c_end)]
            return {'rect': (start_r, start_c, r_end, c_end), 'h': h, 'w': w,
                   'interior': interior, 'is_2x2': (h-2==2 and w-2==2)}

        return None

    for r, c in sorted(target_pos):
        if (r, c) in visited:
            continue
        rect_info = expand_rect(r, c)
        if rect_info:
            frames.append(rect_info)
            visited.update(rect_info['interior'])

    return frames

